steps.action:
curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "types=public_channel" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        print(ch['id'], ch['name'])
else:
    print('Error:', data)
"

curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for u in data['members']:
        print(u['id'], u['real_name'] or u['profile']['real_name'] or '', u['profile']['display_name'])
else:
    print('Error:', data)
"
